const updateGithubWriteIntentState = `-- name: UpdateGithubWriteIntentState :one
UPDATE github_write_intent SET
    state           = $1,
    github_id       = COALESCE($2, github_id),
    issue_id        = COALESCE($3, issue_id),
    external_number = COALESCE($4, external_number),
    comment_id      = COALESCE($5, comment_id),
    error           = $6,
    updated_at      = now()
WHERE id = $7
  AND workspace_id = $8
  AND state NOT IN ('applied', 'failed')
RETURNING id, workspace_id, op, repo_id, external_repo, issue_id, external_number, comment_id, payload_digest, actor_type, actor_id, state, github_id, error, created_at, updated_at
`

type UpdateGithubWriteIntentStateParams struct {
	State          string      `json:"state"`
	GithubID       pgtype.Int8 `json:"github_id"`
	IssueID        pgtype.UUID `json:"issue_id"`
	ExternalNumber pgtype.Int4 `json:"external_number"`
	CommentID      pgtype.UUID `json:"comment_id"`
	Error          pgtype.Text `json:"error"`
	ID             pgtype.UUID `json:"id"`
	WorkspaceID    pgtype.UUID `json:"workspace_id"`
}

// Moves an intent between states. A NULL argument keeps the stored value, so
// a later transition never erases the github_id or target learned earlier.
// Settled intents (applied, failed) are final and are not updated.
func (q *Queries) UpdateGithubWriteIntentState(ctx context.Context, arg UpdateGithubWriteIntentStateParams) (GithubWriteIntent, error) {
	row := q.db.QueryRow(ctx, updateGithubWriteIntentState,
		arg.State,
		arg.GithubID,
		arg.IssueID,
		arg.ExternalNumber,
		arg.CommentID,
		arg.Error,
		arg.ID,
		arg.WorkspaceID,
	)
	var i GithubWriteIntent
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Op,
		&i.RepoID,
		&i.ExternalRepo,
		&i.IssueID,
		&i.ExternalNumber,
		&i.CommentID,
		&i.PayloadDigest,
		&i.ActorType,
		&i.ActorID,
		&i.State,
		&i.GithubID,
		&i.Error,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertCommentExternal = `-- name: UpsertCommentExternal :one

INSERT INTO comment_external (
    comment_id, workspace_id, external_id, login, avatar_url, external_updated_at
) VALUES (
    $1, $2, $3, $4, $5, $6
)
ON CONFLICT (comment_id) DO UPDATE SET
    login               = CASE WHEN EXCLUDED.external_updated_at >= comment_external.external_updated_at
                               THEN EXCLUDED.login ELSE comment_external.login END,
    avatar_url          = CASE WHEN EXCLUDED.external_updated_at >= comment_external.external_updated_at
                               THEN EXCLUDED.avatar_url ELSE comment_external.avatar_url END,
    external_updated_at = GREATEST(EXCLUDED.external_updated_at, comment_external.external_updated_at),
    updated_at          = now()
WHERE comment_external.workspace_id = EXCLUDED.workspace_id
RETURNING comment_id, workspace_id, external_id, login, avatar_url, external_updated_at, created_at, updated_at
`

type UpsertCommentExternalParams struct {
	CommentID         pgtype.UUID        `json:"comment_id"`
	WorkspaceID       pgtype.UUID        `json:"workspace_id"`
	ExternalID        int64              `json:"external_id"`
	Login             string             `json:"login"`
	AvatarUrl         pgtype.Text        `json:"avatar_url"`
	ExternalUpdatedAt pgtype.Timestamptz `json:"external_updated_at"`
}

// ---------------------------------------------------------------------------
// comment_external
// ---------------------------------------------------------------------------
// Same freshness rule as UpsertIssueExternal: an older snapshot never
// overwrites a newer one.
func (q *Queries) UpsertCommentExternal(ctx context.Context, arg UpsertCommentExternalParams) (CommentExternal, error) {
	row := q.db.QueryRow(ctx, upsertCommentExternal,
		arg.CommentID,
		arg.WorkspaceID,
		arg.ExternalID,
		arg.Login,
		arg.AvatarUrl,
		arg.ExternalUpdatedAt,
	)
	var i CommentExternal
	err := row.Scan(
		&i.CommentID,
		&i.WorkspaceID,
		&i.ExternalID,
		&i.Login,
		&i.AvatarUrl,
		&i.ExternalUpdatedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

