// Modified for the mouse9527/multica fork: GitHub-native issues.
// Tables come from migration 9000; see it for column semantics.
// ---------------------------------------------------------------------------
// issue_external
// ---------------------------------------------------------------------------
// The GitHub fields are refreshed only when the incoming snapshot is not older
// than the stored one, so an out-of-order poll page cannot roll a row back.
// The returned row is the stored state after the call.
func (q *Queries) UpsertIssueExternal(ctx context.Context, arg UpsertIssueExternalParams) (IssueExternal, error) {
	row := q.db.QueryRow(ctx, upsertIssueExternal,
		arg.IssueID,
		arg.WorkspaceID,
		arg.Provider,
		arg.ExternalRepoID,
		arg.ExternalRepo,
		arg.ExternalNumber,
		arg.ExternalNodeID,
		arg.State,
		arg.StateReason,
		arg.ExternalUpdatedAt,
	)
	var i IssueExternal
	err := row.Scan(
		&i.IssueID,
		&i.WorkspaceID,
		&i.Provider,
		&i.ExternalRepoID,
		&i.ExternalRepo,
		&i.ExternalNumber,
		&i.ExternalNodeID,
		&i.State,
		&i.StateReason,
		&i.ExternalUpdatedAt,
		&i.ExternalSyncedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

